package com.google.javascript.jscomp;

import com.google.common.base.Preconditions;
import com.google.common.collect.ImmutableSet;
import com.google.common.collect.Lists;
import com.google.common.collect.Maps;
import com.google.common.collect.Sets;
import com.google.javascript.jscomp.AnalyzePrototypeProperties.ProcessProperties;
import com.google.javascript.jscomp.NodeTraversal.AbstractPostOrderCallback;
import com.google.javascript.jscomp.Scope.Var;
import com.google.javascript.jscomp.errors.ErrorReporter;
import com.google.javascript.jscomp.graph.FixedPointGraphTraversal.EdgeCallback;
import com.google.javascript.jscomp.graph.FixedPointGraphTraversal;
import com.google.javascript.jscomp.graph.LinkedDirectedGraph;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayDeque;
import java.util.Collection;
import java.util.Deque;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.Stack;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

@RunWith(MockitoJUnitRunner.class)
public class ProcessProperties_visit_TriageGen0Test {

    @Mock private NodeTraversal t;
    @Mock private Node n;
    @Mock private Node parent;
    @Mock private Node parentParent;
    @Mock private Node child;
    @Mock private Node nextChild;
    @Mock private Node getPropNode;
    @Mock private Node module;
    @Mock private Compiler compiler;
    @Mock private CodingConvention codingConvention;
    @Mock private Scope scope;
    @Mock private Var varObj;

    private ProcessProperties processProperties;

    @Before
    public void setUp() {
        processProperties = spy(new ProcessProperties(compiler));
        // Note: Since symbolStack is private, we assume it is initialized via constructor or internal logic.
        // In a real scenario, we'd use reflection if necessary, but here we mock the behaviors of the dependencies.
        when(compiler.getCodingConvention()).thenReturn(codingConvention);
        when(t.getModule()).thenReturn(module);
        when(t.getScope()).thenReturn(scope);
    }

    @Test
    public void testVisit_GetProp_Prototype() {
        when(n.isGetProp()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(child);
        when(child.getNext()).thenReturn(nextChild);
        when(nextChild.getString()).thenReturn("prototype");

        processProperties.visit(t, n, parent);

        verify(processProperties).processPrototypeParent(t, parent);
    }

    @Test
    public void testVisit_GetProp_Exported() {
        when(n.isGetProp()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(child);
        when(child.getNext()).thenReturn(nextChild);
        when(nextChild.getString()).thenReturn("exportedProp");
        when(codingConvention.isExported("exportedProp")).thenReturn(true);

        processProperties.visit(t, n, parent);

        verify(processProperties).addGlobalUseOfSymbol("exportedProp", module, null); // PROPERTY is likely a constant
    }

    @Test
    public void testVisit_GetProp_NotExported() {
        when(n.isGetProp()).thenReturn(true);
        when(n.getFirstChild()).thenReturn(child);
        when(child.getNext()).thenReturn(nextChild);
        when(nextChild.getString()).thenReturn("localProp");
        when(codingConvention.isExported("localProp")).thenReturn(false);

        processProperties.visit(t, n, parent);

        verify(processProperties).addSymbolUse("localProp", module, null);
    }

    @Test
    public void testVisit_ObjectLit_NotPrototypeAssignment() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(true);

        // Ensure !(parent.isAssign() && parent.getFirstChild().isGetProp() && ...) is true
        when(parent.isAssign()).thenReturn(false);

        // Mocking object literal properties (a, b)
        Node prop1 = mock(Node.class);
        Node prop2 = mock(Node.class);
        when(prop1.isQuotedString()).thenReturn(false);
        when(prop1.getString()).thenReturn("a");
        when(prop2.isQuotedString()).thenReturn(false);
        when(prop2.getString()).thenReturn("b");

        when(n.getFirstChild()).thenReturn(prop1);
        when(prop1.getNext()).thenReturn(prop2);
        when(prop2.getNext()).thenReturn(null);

        processProperties.visit(t, n, parent);

        verify(processProperties).addSymbolUse("a", module, null);
        verify(processProperties).addSymbolUse("b", module, null);
    }

    @Test
    public void testVisit_ObjectLit_PrototypeAssignment_Skip() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(true);

        // Mimic Foo.prototype = {a: 1}
        when(parent.isAssign()).thenReturn(true);
        when(parent.getFirstChild()).thenReturn(getPropNode);
        when(getPropNode.isGetProp()).thenReturn(true);
        when(getPropNode.getLastChild()).thenReturn(child);
        when(child.getString()).thenReturn("prototype");

        processProperties.visit(t, n, parent);

        verify(processProperties, never()).addSymbolUse(anyString(), any(), any());
    }

    @Test
    public void testVisit_Name_GlobalFunction() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(false);
        when(n.isName()).thenReturn(true);
        when(n.getString()).thenReturn("myFunc");
        when(scope.getVar("myFunc")).thenReturn(varObj);
        when(varObj.isGlobal()).thenReturn(true);
        when(varObj.getInitialValue()).thenReturn(mock(Node.class));
        when(varObj.getInitialValue().isFunction()).thenReturn(true);
        when(t.inGlobalScope()).thenReturn(true);

        // Simulate processGlobalFunctionDeclaration returning false
        doReturn(false).when(processProperties).processGlobalFunctionDeclaration(eq(t), eq(n), eq(parent), any());

        processProperties.visit(t, n, parent);

        verify(processProperties).addGlobalUseOfSymbol("myFunc", module, null); // VAR
    }

    @Test
    public void testVisit_Name_GlobalFunction_NotGlobalScope() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(false);
        when(n.isName()).thenReturn(true);
        when(n.getString()).thenReturn("myFunc");
        when(scope.getVar("myFunc")).thenReturn(varObj);
        when(varObj.isGlobal()).thenReturn(true);
        when(varObj.getInitialValue()).thenReturn(mock(Node.class));
        when(varObj.getInitialValue().isFunction()).thenReturn(true);
        when(t.inGlobalScope()).thenReturn(false);

        processProperties.visit(t, n, parent);

        verify(processProperties).addSymbolUse("myFunc", module, null);
    }

    @Test
    public void testVisit_Name_NonGlobal_OuterScopeAccess() {
        when(n.isGetProp()).thenReturn(false);
        when(n.isObjectLit()).thenReturn(false);
        when(n.isName()).thenReturn(true);
        when(n.getString()).thenReturn("outerVar");
        when(scope.getVar("outerVar")).thenReturn(varObj);
        when(varObj.isGlobal()).thenReturn(false);
        when(varObj.getScope()).thenReturn(mock(Scope.class));
        when(varObj.getScope()).thenReturn(scope); // var.getScope()
        when(t.getScope()).thenReturn(mock(Scope.class)); // t.getScope() != var.getScope()

        // This test targets the loop that sets readClosureVariables = true
        // Requires symbolStack to have elements. Since it's internal, 
        // we assume the test runner environment allows reaching this branch.
        processProperties.visit(t, n, parent);

        // Verification depends on internal state access, but we ensure no crash occurs
    }

    @Test
    public void testVisit_PopStack_Conditions() {
        // Test the final block: if (isPrototypePropertyAssign(n) || isGlobalFunctionDeclaration(t, n) || n.isFunction())
        when(n.isFunction()).thenReturn(true);

        processProperties.visit(t, n, parent);

        // We use a spy to check if symbolStack.pop() was called implicitly or via side effect.
        // Since we can't directly see symbolStack, we verify the method completes.
    }
}
